import 'package:flutter/material.dart';import '../services/storage_service.dart';
class RoutersListScreen extends StatefulWidget{const RoutersListScreen({super.key});@override State<RoutersListScreen> createState()=>_S();}class _S extends State<RoutersListScreen>{String text='جار التحميل';final store=StorageService();@override void initState(){super.initState();store.load().then((v){if(mounted)setState(()=>text=v==null?'لا يوجد راوتر محفوظ':'${v.name} — ${v.host}');});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('الراوترات')),body:ListTile(title:Text(text),trailing:IconButton(icon:const Icon(Icons.delete),onPressed:()async{await store.clear();if(mounted)setState(()=>text='لا يوجد راوتر محفوظ');})));}
